INSERT INTO posts (type, status, slug, title, excerpt, content, meta_title, meta_description, author_id, published_at)
VALUES (
  'post',
  'draft',
  'from-zero-to-kickass-engineer-with-ai',
  'From Zero to Kickass Software Engineer: Using AI as Your Unfair Advantage',
  'No coding background? A practical 90-day roadmap for using AI as tutor, pair programmer, and reviewer to become a job-ready software engineer.',
  '{"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"From Zero to Kickass Software Engineer: Using AI as Your Unfair Advantage"}]},{"type":"paragraph","content":[{"type":"text","text":"Five years ago, learning to code from scratch meant months of lonely tutorial hell before you could build anything real. Today, AI coding assistants — tools like ChatGPT, Claude, and Muse that generate and explain code from plain-English prompts — have flattened that curve. A motivated beginner can ship a working app in week one."}]},{"type":"paragraph","content":[{"type":"text","text":"But here is the uncomfortable truth: AI will happily generate code you don''t understand, and engineers who can''t explain their own code don''t stay employed. The people winning with AI aren''t skipping the fundamentals — they''re learning them "},{"type":"text","marks":[{"type":"italic"}],"text":"faster"},{"type":"text","text":" by using AI as a tutor, pair programmer, and code reviewer."}]},{"type":"paragraph","content":[{"type":"text","text":"This guide is a practical roadmap for going from zero software background to job-ready engineer, with AI as leverage at every step."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The Mindset Shift: AI Is Leverage, Not a Shortcut"}]},{"type":"paragraph","content":[{"type":"text","text":"Think of AI as a senior engineer sitting next to you 24/7 — infinitely patient, occasionally wrong. Your job is to become the engineer who directs it, questions it, and verifies its output. That means:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"You write the spec, AI writes the first draft."},{"type":"text","text":" Describe what you want in plain English, then read every line it produces."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"You ask \"why\", relentlessly."},{"type":"text","text":" Every AI-generated line you can''t explain is a gap in your knowledge. Turn gaps into questions."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"You own the result."},{"type":"text","text":" If the code breaks in production, \"the AI wrote it\" is not an excuse. Understanding is non-negotiable."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Internalize this and you avoid the number-one failure mode: becoming a "},{"type":"text","marks":[{"type":"italic"}],"text":"prompt operator"},{"type":"text","text":" who can demo but can''t debug."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Phase 1: Foundations With an AI Tutor (Weeks 1–4)"}]},{"type":"paragraph","content":[{"type":"text","text":"Pick "},{"type":"text","marks":[{"type":"bold"}],"text":"one"},{"type":"text","text":" language. For most beginners, "},{"type":"text","marks":[{"type":"bold"}],"text":"Python"},{"type":"text","text":" (readable, huge job market) or "},{"type":"text","marks":[{"type":"bold"}],"text":"JavaScript"},{"type":"text","text":" (runs in every browser, powers the web) is the right call. Don''t agonize — concepts transfer."}]},{"type":"paragraph","content":[{"type":"text","text":"Learn these in order, using AI as your personal tutor:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"How software actually runs"},{"type":"text","text":" — files, the terminal (a text-based way to control your computer), and how code becomes a running program."}]},{"type":"details","attrs":{"open":false},"content":[{"type":"detailsSummary","content":[{"type":"text","text":"🖼️ See it in pictures: how desktop and web apps run"}]},{"type":"paragraph","content":[{"type":"text","text":"Words are forgettable — pictures stick. Trace each journey with your finger:"}]},{"type":"paragraph"},{"type":"image","attrs":{"src":"/diagrams/how-desktop-app-runs.svg","alt":"How a desktop app runs: you double-click, the disk wakes the file, it loads into memory, the CPU runs the instructions, and results appear on screen","title":null}},{"type":"paragraph","content":[{"type":"text","text":"A desktop app is a one-computer story: everything happens on your own machine. The disk remembers, the memory thinks fast, and the CPU does the work."}]},{"type":"paragraph"},{"type":"image","attrs":{"src":"/diagrams/how-web-app-runs.svg","alt":"How a web app runs: your browser talks HTTPS on port 443 through a firewall and CDN to a web server, API server, cache, and database","title":null}},{"type":"paragraph","content":[{"type":"text","text":"A web app is a team sport played across the internet. The new words, kid-style:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Port"},{"type":"text","text":" — the apartment number on a server building. Web traffic knocks on door 443."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Protocol"},{"type":"text","text":" — the language spoken at the door. HTTPS is HTTP with a secret handshake (locked 🔒)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Firewall"},{"type":"text","text":" — the bouncer who turns away troublemakers."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"CDN"},{"type":"text","text":" — photocopies of pictures and files, stored in cities near you so they load fast."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Web server"},{"type":"text","text":" — the front door that greets every browser."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"API"},{"type":"text","text":" — the menu of orders the kitchen accepts (\"give me user number 5, please!\")."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Cache"},{"type":"text","text":" — sticky notes with remembered answers, so nobody repeats work."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Database"},{"type":"text","text":" — the filing cabinets where everything is really kept."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Follow-up exercise for your AI tutor: \"I just learned what ports, protocols, and caches are. Quiz me with 5 questions, easy to hard.\""}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Core programming concepts"},{"type":"text","text":" — variables, loops, conditionals, functions, and basic data structures like lists and dictionaries."}]},{"type":"details","attrs":{"open":false},"content":[{"type":"detailsSummary","content":[{"type":"text","text":"🍎 Brand new to code? Click here — variables, loops & friends, explained like you''re 10"}]},{"type":"paragraph","content":[{"type":"text","text":"Think of the computer as a super-fast helper who takes everything very literally. It only understands a few simple ideas. Master these six and you can read almost any beginner program. Each example speaks 7 languages — flip the tabs! (Go and Rust fragments assume the usual "},{"type":"text","marks":[{"type":"code"}],"text":"main"},{"type":"text","text":" wrapper and imports.)"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"📦 Variables = labeled boxes"}]},{"type":"paragraph","content":[{"type":"text","text":"A variable is a box with a name tag. You put something in, and later you ask for it by name."}]},{"type":"codeTabs","content":[{"type":"codeTab","attrs":{"label":"Python","language":"python"},"content":[{"type":"codeBlock","attrs":{"language":"python"},"content":[{"type":"text","text":"favorite_snack = \"cookies\"\nslices_eaten = 2"}]}]},{"type":"codeTab","attrs":{"label":"JavaScript","language":"javascript"},"content":[{"type":"codeBlock","attrs":{"language":"javascript"},"content":[{"type":"text","text":"let favorite_snack = \"cookies\";\nlet slices_eaten = 2;"}]}]},{"type":"codeTab","attrs":{"label":"TypeScript","language":"typescript"},"content":[{"type":"codeBlock","attrs":{"language":"typescript"},"content":[{"type":"text","text":"let favorite_snack: string = \"cookies\";\nlet slices_eaten: number = 2;"}]}]},{"type":"codeTab","attrs":{"label":"Go","language":"go"},"content":[{"type":"codeBlock","attrs":{"language":"go"},"content":[{"type":"text","text":"favorite_snack := \"cookies\"\nslices_eaten := 2"}]}]},{"type":"codeTab","attrs":{"label":"Rust","language":"rust"},"content":[{"type":"codeBlock","attrs":{"language":"rust"},"content":[{"type":"text","text":"let favorite_snack = \"cookies\";\nlet slices_eaten = 2;"}]}]},{"type":"codeTab","attrs":{"label":"Ruby","language":"ruby"},"content":[{"type":"codeBlock","attrs":{"language":"ruby"},"content":[{"type":"text","text":"favorite_snack = \"cookies\"\nslices_eaten = 2"}]}]},{"type":"codeTab","attrs":{"label":"PHP","language":"php"},"content":[{"type":"codeBlock","attrs":{"language":"php"},"content":[{"type":"text","text":"$favorite_snack = \"cookies\";\n$slices_eaten = 2;"}]}]}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"favorite_snack"},{"type":"text","text":" is the name tag, "},{"type":"text","marks":[{"type":"code"}],"text":"\"cookies\""},{"type":"text","text":" is what''s inside the box. The single "},{"type":"text","marks":[{"type":"code"}],"text":"="},{"type":"text","text":" means \"put this inside\" (it is not the equals sign from math class!). Every language dresses boxes a little differently — PHP names start with "},{"type":"text","marks":[{"type":"code"}],"text":"$"},{"type":"text","text":", Go uses "},{"type":"text","marks":[{"type":"code"}],"text":":="},{"type":"text","text":" to fill a box for the first time — but the idea is identical."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"🚦 Conditionals = choose-your-own-adventure"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"if"},{"type":"text","text":" lets the program make decisions, just like you do: "},{"type":"text","marks":[{"type":"italic"}],"text":"if"},{"type":"text","text":" it''s raining, "},{"type":"text","marks":[{"type":"italic"}],"text":"then"},{"type":"text","text":" grab an umbrella, "},{"type":"text","marks":[{"type":"italic"}],"text":"otherwise"},{"type":"text","text":" wear sunglasses."}]},{"type":"codeTabs","content":[{"type":"codeTab","attrs":{"label":"Python","language":"python"},"content":[{"type":"codeBlock","attrs":{"language":"python"},"content":[{"type":"text","text":"if slices_eaten >= 3:\n    print(\"Slow down, champ!\")\nelse:\n    print(\"Enjoy your snack!\")"}]}]},{"type":"codeTab","attrs":{"label":"JavaScript","language":"javascript"},"content":[{"type":"codeBlock","attrs":{"language":"javascript"},"content":[{"type":"text","text":"if (slices_eaten >= 3) {\n  console.log(\"Slow down, champ!\");\n} else {\n  console.log(\"Enjoy your snack!\");\n}"}]}]},{"type":"codeTab","attrs":{"label":"TypeScript","language":"typescript"},"content":[{"type":"codeBlock","attrs":{"language":"typescript"},"content":[{"type":"text","text":"if (slices_eaten >= 3) {\n  console.log(\"Slow down, champ!\");\n} else {\n  console.log(\"Enjoy your snack!\");\n}"}]}]},{"type":"codeTab","attrs":{"label":"Go","language":"go"},"content":[{"type":"codeBlock","attrs":{"language":"go"},"content":[{"type":"text","text":"if slices_eaten >= 3 {\n  fmt.Println(\"Slow down, champ!\")\n} else {\n  fmt.Println(\"Enjoy your snack!\")\n}"}]}]},{"type":"codeTab","attrs":{"label":"Rust","language":"rust"},"content":[{"type":"codeBlock","attrs":{"language":"rust"},"content":[{"type":"text","text":"if slices_eaten >= 3 {\n  println!(\"Slow down, champ!\");\n} else {\n  println!(\"Enjoy your snack!\");\n}"}]}]},{"type":"codeTab","attrs":{"label":"Ruby","language":"ruby"},"content":[{"type":"codeBlock","attrs":{"language":"ruby"},"content":[{"type":"text","text":"if slices_eaten >= 3\n  puts \"Slow down, champ!\"\nelse\n  puts \"Enjoy your snack!\"\nend"}]}]},{"type":"codeTab","attrs":{"label":"PHP","language":"php"},"content":[{"type":"codeBlock","attrs":{"language":"php"},"content":[{"type":"text","text":"if ($slices_eaten >= 3) {\n  echo \"Slow down, champ!\";\n} else {\n  echo \"Enjoy your snack!\";\n}"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The program checks the question after "},{"type":"text","marks":[{"type":"code"}],"text":"if"},{"type":"text","text":". If the answer is yes, it runs the first block; if no, it runs the "},{"type":"text","marks":[{"type":"code"}],"text":"else"},{"type":"text","text":" block. (Notice "},{"type":"text","marks":[{"type":"code"}],"text":">="},{"type":"text","text":" means \"greater than or equal to\" — two characters working as one question.)"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"🎠 Loops = the merry-go-round"}]},{"type":"paragraph","content":[{"type":"text","text":"A loop repeats something without you having to write it over and over. A "},{"type":"text","marks":[{"type":"code"}],"text":"for"},{"type":"text","text":" loop says: \"do this once for every item.\""}]},{"type":"codeTabs","content":[{"type":"codeTab","attrs":{"label":"Python","language":"python"},"content":[{"type":"codeBlock","attrs":{"language":"python"},"content":[{"type":"text","text":"for friend in [\"Ana\", \"Ben\", \"Cory\"]:\n    print(\"High five, \" + friend + \"!\")"}]}]},{"type":"codeTab","attrs":{"label":"JavaScript","language":"javascript"},"content":[{"type":"codeBlock","attrs":{"language":"javascript"},"content":[{"type":"text","text":"for (const friend of [\"Ana\", \"Ben\", \"Cory\"]) {\n  console.log(\"High five, \" + friend + \"!\");\n}"}]}]},{"type":"codeTab","attrs":{"label":"TypeScript","language":"typescript"},"content":[{"type":"codeBlock","attrs":{"language":"typescript"},"content":[{"type":"text","text":"for (const friend of [\"Ana\", \"Ben\", \"Cory\"]) {\n  console.log(\"High five, \" + friend + \"!\");\n}"}]}]},{"type":"codeTab","attrs":{"label":"Go","language":"go"},"content":[{"type":"codeBlock","attrs":{"language":"go"},"content":[{"type":"text","text":"for _, friend := range []string{\"Ana\", \"Ben\", \"Cory\"} {\n  fmt.Println(\"High five, \" + friend + \"!\")\n}"}]}]},{"type":"codeTab","attrs":{"label":"Rust","language":"rust"},"content":[{"type":"codeBlock","attrs":{"language":"rust"},"content":[{"type":"text","text":"for friend in [\"Ana\", \"Ben\", \"Cory\"] {\n  println!(\"High five, {friend}!\");\n}"}]}]},{"type":"codeTab","attrs":{"label":"Ruby","language":"ruby"},"content":[{"type":"codeBlock","attrs":{"language":"ruby"},"content":[{"type":"text","text":"for friend in [\"Ana\", \"Ben\", \"Cory\"]\n  puts \"High five, #{friend}!\"\nend"}]}]},{"type":"codeTab","attrs":{"label":"PHP","language":"php"},"content":[{"type":"codeBlock","attrs":{"language":"php"},"content":[{"type":"text","text":"foreach ([\"Ana\", \"Ben\", \"Cory\"] as $friend) {\n  echo \"High five, $friend!\";\n}"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"This prints three high-fives — one per friend. The loop grabs each name, puts it in the variable "},{"type":"text","marks":[{"type":"code"}],"text":"friend"},{"type":"text","text":", and runs the print. Round and round until the list is empty!"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"📖 Functions = recipes"}]},{"type":"paragraph","content":[{"type":"text","text":"A function is a named set of steps you can reuse anytime, like a recipe. You define it once with "},{"type":"text","marks":[{"type":"code"}],"text":"def"},{"type":"text","text":", then \"call\" it by name whenever you''re hungry for results."}]},{"type":"codeTabs","content":[{"type":"codeTab","attrs":{"label":"Python","language":"python"},"content":[{"type":"codeBlock","attrs":{"language":"python"},"content":[{"type":"text","text":"def greet(name):\n    return \"Hello, \" + name + \"!\"\n\nprint(greet(\"Ana\"))\nprint(greet(\"Ben\"))"}]}]},{"type":"codeTab","attrs":{"label":"JavaScript","language":"javascript"},"content":[{"type":"codeBlock","attrs":{"language":"javascript"},"content":[{"type":"text","text":"function greet(name) {\n  return \"Hello, \" + name + \"!\";\n}\n\nconsole.log(greet(\"Ana\"));\nconsole.log(greet(\"Ben\"));"}]}]},{"type":"codeTab","attrs":{"label":"TypeScript","language":"typescript"},"content":[{"type":"codeBlock","attrs":{"language":"typescript"},"content":[{"type":"text","text":"function greet(name: string): string {\n  return \"Hello, \" + name + \"!\";\n}\n\nconsole.log(greet(\"Ana\"));\nconsole.log(greet(\"Ben\"));"}]}]},{"type":"codeTab","attrs":{"label":"Go","language":"go"},"content":[{"type":"codeBlock","attrs":{"language":"go"},"content":[{"type":"text","text":"func greet(name string) string {\n  return \"Hello, \" + name + \"!\"\n}\n\nfmt.Println(greet(\"Ana\"))\nfmt.Println(greet(\"Ben\"))"}]}]},{"type":"codeTab","attrs":{"label":"Rust","language":"rust"},"content":[{"type":"codeBlock","attrs":{"language":"rust"},"content":[{"type":"text","text":"fn greet(name: &str) -> String {\n  format!(\"Hello, {name}!\")\n}\n\nprintln!(\"{}\", greet(\"Ana\"));\nprintln!(\"{}\", greet(\"Ben\"));"}]}]},{"type":"codeTab","attrs":{"label":"Ruby","language":"ruby"},"content":[{"type":"codeBlock","attrs":{"language":"ruby"},"content":[{"type":"text","text":"def greet(name)\n  \"Hello, \" + name + \"!\"\nend\n\nputs greet(\"Ana\")\nputs greet(\"Ben\")"}]}]},{"type":"codeTab","attrs":{"label":"PHP","language":"php"},"content":[{"type":"codeBlock","attrs":{"language":"php"},"content":[{"type":"text","text":"function greet($name) {\n  return \"Hello, \" . $name . \"!\";\n}\n\necho greet(\"Ana\");\necho greet(\"Ben\");"}]}]}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"greet"},{"type":"text","text":" is the recipe''s name, "},{"type":"text","marks":[{"type":"code"}],"text":"name"},{"type":"text","text":" is the ingredient you hand it, and "},{"type":"text","marks":[{"type":"code"}],"text":"return"},{"type":"text","text":" is the finished dish it hands back. Write once, eat twice!"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"🧺 Lists = a row of cubbies"}]},{"type":"paragraph","content":[{"type":"text","text":"A list holds many things in order, like cubbies in a classroom — except computers start counting at "},{"type":"text","marks":[{"type":"bold"}],"text":"0"},{"type":"text","text":" (silly, but true: the first cubby is number 0)."}]},{"type":"codeTabs","content":[{"type":"codeTab","attrs":{"label":"Python","language":"python"},"content":[{"type":"codeBlock","attrs":{"language":"python"},"content":[{"type":"text","text":"snacks = [\"cookies\", \"apples\", \"cheese\"]\nprint(snacks[0])  # cookies — the FIRST cubby\nprint(snacks[2])  # cheese — the THIRD cubby"}]}]},{"type":"codeTab","attrs":{"label":"JavaScript","language":"javascript"},"content":[{"type":"codeBlock","attrs":{"language":"javascript"},"content":[{"type":"text","text":"const snacks = [\"cookies\", \"apples\", \"cheese\"];\nconsole.log(snacks[0]); // cookies — the FIRST cubby\nconsole.log(snacks[2]); // cheese — the THIRD cubby"}]}]},{"type":"codeTab","attrs":{"label":"TypeScript","language":"typescript"},"content":[{"type":"codeBlock","attrs":{"language":"typescript"},"content":[{"type":"text","text":"const snacks: string[] = [\"cookies\", \"apples\", \"cheese\"];\nconsole.log(snacks[0]); // cookies — the FIRST cubby\nconsole.log(snacks[2]); // cheese — the THIRD cubby"}]}]},{"type":"codeTab","attrs":{"label":"Go","language":"go"},"content":[{"type":"codeBlock","attrs":{"language":"go"},"content":[{"type":"text","text":"snacks := []string{\"cookies\", \"apples\", \"cheese\"}\nfmt.Println(snacks[0]) // cookies — the FIRST cubby\nfmt.Println(snacks[2]) // cheese — the THIRD cubby"}]}]},{"type":"codeTab","attrs":{"label":"Rust","language":"rust"},"content":[{"type":"codeBlock","attrs":{"language":"rust"},"content":[{"type":"text","text":"let snacks = [\"cookies\", \"apples\", \"cheese\"];\nprintln!(\"{}\", snacks[0]); // cookies — the FIRST cubby\nprintln!(\"{}\", snacks[2]); // cheese — the THIRD cubby"}]}]},{"type":"codeTab","attrs":{"label":"Ruby","language":"ruby"},"content":[{"type":"codeBlock","attrs":{"language":"ruby"},"content":[{"type":"text","text":"snacks = [\"cookies\", \"apples\", \"cheese\"]\nputs snacks[0] # cookies — the FIRST cubby\nputs snacks[2] # cheese — the THIRD cubby"}]}]},{"type":"codeTab","attrs":{"label":"PHP","language":"php"},"content":[{"type":"codeBlock","attrs":{"language":"php"},"content":[{"type":"text","text":"$snacks = [\"cookies\", \"apples\", \"cheese\"];\necho $snacks[0]; // cookies — the FIRST cubby\necho $snacks[2]; // cheese — the THIRD cubby"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Square brackets pick a cubby by number. ("},{"type":"text","marks":[{"type":"code"}],"text":"#"},{"type":"text","text":" starts a comment — a note for humans that the computer ignores.)"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"🗝️ Dictionaries = lockers with name labels"}]},{"type":"paragraph","content":[{"type":"text","text":"A dictionary also stores many things, but instead of cubby "},{"type":"text","marks":[{"type":"italic"}],"text":"numbers"},{"type":"text","text":" you use name "},{"type":"text","marks":[{"type":"italic"}],"text":"labels"},{"type":"text","text":" (called \"keys\"). Just like a real dictionary: look up a word, get its meaning."}]},{"type":"codeTabs","content":[{"type":"codeTab","attrs":{"label":"Python","language":"python"},"content":[{"type":"codeBlock","attrs":{"language":"python"},"content":[{"type":"text","text":"ages = {\"Ana\": 10, \"Ben\": 11}\nprint(ages[\"Ben\"])  # 11"}]}]},{"type":"codeTab","attrs":{"label":"JavaScript","language":"javascript"},"content":[{"type":"codeBlock","attrs":{"language":"javascript"},"content":[{"type":"text","text":"const ages = { Ana: 10, Ben: 11 };\nconsole.log(ages[\"Ben\"]); // 11"}]}]},{"type":"codeTab","attrs":{"label":"TypeScript","language":"typescript"},"content":[{"type":"codeBlock","attrs":{"language":"typescript"},"content":[{"type":"text","text":"const ages: Record<string, number> = { Ana: 10, Ben: 11 };\nconsole.log(ages[\"Ben\"]); // 11"}]}]},{"type":"codeTab","attrs":{"label":"Go","language":"go"},"content":[{"type":"codeBlock","attrs":{"language":"go"},"content":[{"type":"text","text":"ages := map[string]int{\"Ana\": 10, \"Ben\": 11}\nfmt.Println(ages[\"Ben\"]) // 11"}]}]},{"type":"codeTab","attrs":{"label":"Rust","language":"rust"},"content":[{"type":"codeBlock","attrs":{"language":"rust"},"content":[{"type":"text","text":"use std::collections::HashMap;\nlet mut ages = HashMap::new();\nages.insert(\"Ana\", 10);\nages.insert(\"Ben\", 11);\nprintln!(\"{}\", ages[\"Ben\"]); // 11"}]}]},{"type":"codeTab","attrs":{"label":"Ruby","language":"ruby"},"content":[{"type":"codeBlock","attrs":{"language":"ruby"},"content":[{"type":"text","text":"ages = { \"Ana\" => 10, \"Ben\" => 11 }\nputs ages[\"Ben\"] # 11"}]}]},{"type":"codeTab","attrs":{"label":"PHP","language":"php"},"content":[{"type":"codeBlock","attrs":{"language":"php"},"content":[{"type":"text","text":"$ages = [\"Ana\" => 10, \"Ben\" => 11];\necho $ages[\"Ben\"]; // 11"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Curly braces "},{"type":"text","marks":[{"type":"code"}],"text":"{}"},{"type":"text","text":" hold pairs of "},{"type":"text","marks":[{"type":"code"}],"text":"label: thing"},{"type":"text","text":". Ask for "},{"type":"text","marks":[{"type":"code"}],"text":"\"Ben\""},{"type":"text","text":" and you get "},{"type":"text","marks":[{"type":"code"}],"text":"11"},{"type":"text","text":". No counting cubbies!"}]},{"type":"horizontalRule"},{"type":"paragraph","content":[{"type":"text","text":"That''s the whole starter pack: boxes, decisions, merry-go-rounds, recipes, cubbies, and lockers. Everything else in programming is built from these. Now go ask your AI tutor for exercises — you''ve got this! 💪"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Git and GitHub"},{"type":"text","text":" — Git tracks changes to your code; GitHub hosts it online. Every professional workflow depends on them."}]},{"type":"details","attrs":{"open":false},"content":[{"type":"detailsSummary","content":[{"type":"text","text":"⏰ Git and GitHub: your code time machine (every command, kid-style)"}]},{"type":"paragraph","content":[{"type":"text","text":"Think of Git as a "},{"type":"text","marks":[{"type":"bold"}],"text":"time machine for your code"},{"type":"text","text":". Every "},{"type":"text","marks":[{"type":"code"}],"text":"commit"},{"type":"text","text":" is a save point in a video game — mess up, and you teleport back. GitHub is the "},{"type":"text","marks":[{"type":"bold"}],"text":"clubhouse online"},{"type":"text","text":" where copies of your time machine live, so teammates (and future-you on another computer) can share."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Look around first"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"git status"},{"type":"text","text":" — \"what changed since my last save point?\" Run this ten times a day; it never breaks anything."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"git log --oneline"},{"type":"text","text":" — \"show me the list of save points,\" one per line. Each starts with a short ID like "},{"type":"text","marks":[{"type":"code"}],"text":"a1b2c3d"},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"git show a1b2c3d"},{"type":"text","text":" — \"open that one save point and show me exactly what changed.\""}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"git diff"},{"type":"text","text":" — \"spot the difference between right now and my last save.\""}]}]}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Make save points"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"git init"},{"type":"text","text":" — build a brand-new time machine in this folder. Run once per project, at the start."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"git add"},{"type":"text","text":" — put toys in the gift box (this in-between step is called "},{"type":"text","marks":[{"type":"italic"}],"text":"staging"},{"type":"text","text":"). Nothing is saved yet! Pick what goes in:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"git add ."},{"type":"text","text":" — \"box up EVERYTHING in this folder and below\" — new files, edits, the works. This is the everyday one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"git add *"},{"type":"text","text":" — \"box up everything I can SEE.\" The "},{"type":"text","marks":[{"type":"code"}],"text":"*"},{"type":"text","text":" is the shell''s magnifying glass: it skips hidden dotfiles (like "},{"type":"text","marks":[{"type":"code"}],"text":".env"},{"type":"text","text":"), so plain "},{"type":"text","marks":[{"type":"code"}],"text":"."},{"type":"text","text":" is usually what you want."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"git add shopping.py"},{"type":"text","text":" — box up just one toy. Naming several works too: "},{"type":"text","marks":[{"type":"code"}],"text":"git add eggs.py bacon.py"},{"type":"text","text":"."}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"git commit -m \"Add high-five loop\""},{"type":"text","text":" — wrap the box and write a label on it. Now it''s a save point."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"git tag v1.0"},{"type":"text","text":" — stick a gold star on a special save point, like a finished version."}]}]}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Undo and tidy up"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"git restore oops.py"},{"type":"text","text":" — \"oops, put that file back how it was at my last save.\" Unsaved changes vanish — that''s the point."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"git reset"},{"type":"text","text":" — unwrap the gift box (unstage) but keep your toys. Add "},{"type":"text","marks":[{"type":"code"}],"text":"--hard"},{"type":"text","text":" and the time machine smashes all the way back to the last save, deleting unsaved work — ask your AI tutor before ever using "},{"type":"text","marks":[{"type":"code"}],"text":"--hard"},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"git rm old.py"},{"type":"text","text":" — throw a file away "},{"type":"text","marks":[{"type":"italic"}],"text":"and"},{"type":"text","text":" tell Git about it in one move."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"git mv a.py b.py"},{"type":"text","text":" — rename a file "},{"type":"text","marks":[{"type":"italic"}],"text":"and"},{"type":"text","text":" tell Git in one move."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"git stash"},{"type":"text","text":" — shove unfinished work into a drawer so your desk is clean. "},{"type":"text","marks":[{"type":"code"}],"text":"git stash pop"},{"type":"text","text":" brings it back out."}]}]}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Parallel universes"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"git branch experiment"},{"type":"text","text":" — start a parallel universe to try something risky without touching your good code."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"git switch experiment"},{"type":"text","text":" — hop into that universe. "},{"type":"text","marks":[{"type":"code"}],"text":"git switch main"},{"type":"text","text":" hops home."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"git merge experiment"},{"type":"text","text":" — fold the experiment back into your current universe. Mostly magic; sometimes Git asks you to resolve a "},{"type":"text","marks":[{"type":"italic"}],"text":"conflict"},{"type":"text","text":" (two people edited the same lines) — pick the winner, save, commit."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"git rebase main"},{"type":"text","text":" — replay your universe''s saves on top of the newest "},{"type":"text","marks":[{"type":"code"}],"text":"main"},{"type":"text","text":", like re-stacking blocks neatly. Powerful and slightly spicy — have AI walk you through your first one."}]}]}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Teamwork through GitHub"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"git clone https://github.com/ana/pets.git"},{"type":"text","text":" — photocopy the clubhouse project onto your computer, history and all."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"git fetch"},{"type":"text","text":" — peek at what''s new in the clubhouse without touching any of your stuff."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"git push"},{"type":"text","text":" — send your new save points up to the clubhouse."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"git pull"},{"type":"text","text":" — fetch + merge in one hug: grab the new stuff and fold it into yours."}]}]}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Detective tools"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"git grep \"TODO\""},{"type":"text","text":" — search every file in the whole project for a word, instantly."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"git bisect"},{"type":"text","text":" — find which save point broke the game using the number-guessing trick: Git picks a save in the middle, you answer \"good or broken?\", and it halves the suspects each round until one save is caught red-handed."}]}]}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Wait — what about "},{"type":"text","marks":[{"type":"code"}],"text":"backfill"},{"type":"text","marks":[{"type":"bold"}],"text":"?"}]},{"type":"paragraph","content":[{"type":"text","text":"Trick entry: "},{"type":"text","marks":[{"type":"code"}],"text":"backfill"},{"type":"text","text":" is not a real Git command! It''s a grown-up word for \"fill in missing past stuff later\" — like writing tests for old code, or importing history from somewhere else. If someone asks you to backfill, ask "},{"type":"text","marks":[{"type":"italic"}],"text":"what"},{"type":"text","text":" and "},{"type":"text","marks":[{"type":"italic"}],"text":"with which tool"},{"type":"text","text":", then use the real commands above."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"GitHub walkthrough: your first upstream"}]},{"type":"paragraph","content":[{"type":"text","text":"Made a project on your computer with "},{"type":"text","marks":[{"type":"code"}],"text":"git init"},{"type":"text","text":"? Give it a clubhouse. Create an empty repository on github.com (no README yet), then:"}]},{"type":"codeBlock","attrs":{"language":null},"content":[{"type":"text","text":"git remote add origin https://github.com/YOU/pets.git\ngit push -u origin main\n"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"origin"},{"type":"text","text":" is just the nickname for your clubhouse''s address (\"upstream provider\" in grown-up words). The "},{"type":"text","marks":[{"type":"code"}],"text":"-u"},{"type":"text","text":" means \"remember this, so plain "},{"type":"text","marks":[{"type":"code"}],"text":"git push"},{"type":"text","text":" works from now on.\" Your daily loop becomes: "},{"type":"text","marks":[{"type":"code"}],"text":"pull"},{"type":"text","text":" → work → "},{"type":"text","marks":[{"type":"code"}],"text":"add"},{"type":"text","text":" + "},{"type":"text","marks":[{"type":"code"}],"text":"commit"},{"type":"text","text":" → "},{"type":"text","marks":[{"type":"code"}],"text":"push"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"GitHub Actions: robot helpers"}]},{"type":"paragraph","content":[{"type":"text","text":"Actions are robots that wake up every time you push and check your work — usually by running your tests. Add this file and you have a robot:"}]},{"type":"codeBlock","attrs":{"language":null},"content":[{"type":"text","text":"# .github/workflows/ci.yml\non: [push]\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - run: python -m pytest\n"}]},{"type":"paragraph","content":[{"type":"text","text":"Translation: \"on every push, grab a fresh computer, download my code, run my tests.\" Green check means all good; red X means click it, read what failed, and fix it. Your first Action doesn''t need to be fancy — a robot that runs your tests already puts you ahead of most beginners."}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Reading error messages"},{"type":"text","text":" — the single most underrated beginner skill."}]},{"type":"details","attrs":{"open":false},"content":[{"type":"detailsSummary","content":[{"type":"text","text":"🔍 Turn scary errors into lessons with AI"}]},{"type":"paragraph","content":[{"type":"text","text":"Every error message is secretly a tiny treasure map. It looks scary; it is mostly helpful. Here''s the recipe:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Read the LAST line first."},{"type":"text","text":" That''s the complaint in plain words. "},{"type":"text","marks":[{"type":"code"}],"text":"NameError: name ''greet'' is not defined"},{"type":"text","text":" means \"you used the name "},{"type":"text","marks":[{"type":"code"}],"text":"greet"},{"type":"text","text":", but I never met anyone called that.\""}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Read the file and line number above it."},{"type":"text","text":" That''s the X on the map — "},{"type":"text","marks":[{"type":"code"}],"text":"app.py, line 7"},{"type":"text","text":" tells you exactly where to look."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Copy the WHOLE error"},{"type":"text","text":", not just the last line. The middle lines are the trail of footsteps showing how the program got there."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Then hand it to AI with this template:"}]},{"type":"codeBlock","attrs":{"language":null},"content":[{"type":"text","text":"I''m learning Python. I ran [what you ran] and expected [what you wanted].\nI got this error:\n[paste the FULL error here]\nHere''s my code:\n[paste the smallest code that breaks]\nPlease: 1) explain what the error means like I''m 10,\n2) tell me WHY it happened, 3) show the fix,\n4) show me how to avoid it next time.\n"}]},{"type":"paragraph","content":[{"type":"text","text":"Two rules that make you look senior fast:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Never paste secrets."},{"type":"text","text":" Passwords, API keys, and private company code stay OUT of the chat. Replace them with "},{"type":"text","marks":[{"type":"code"}],"text":"FAKEKEY123"},{"type":"text","text":" before pasting."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Ask for the lesson, not just the fix."},{"type":"text","text":" End with: \"What concept should I study so I truly understand this?\" Then study that — this is how errors become promotions."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Try it now: break something tiny on purpose (delete a colon, misspell a name), read the error with the recipe above, and watch yourself debug like an engineer."}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The trick is "},{"type":"text","marks":[{"type":"italic"}],"text":"how"},{"type":"text","text":" you prompt. Don''t ask for answers — ask for lessons:"}]},{"type":"codeBlock","attrs":{"language":null},"content":[{"type":"text","text":"I''m a beginner learning Python. Explain what a \"for loop\" is using a\nreal-world analogy, then give me 3 small exercises from easy to hard.\nDon''t show me the solutions until I ask.\n"}]},{"type":"paragraph","content":[{"type":"text","text":"Then attempt the exercises, paste your solution back, and ask:"}]},{"type":"codeBlock","attrs":{"language":null},"content":[{"type":"text","text":"Here''s my solution. Review it like a senior engineer mentoring a junior:\npoint out bugs, style issues, and one thing I could do more idiomatically.\n"}]},{"type":"paragraph","content":[{"type":"text","text":"That feedback loop — attempt, review, revise — is worth more than any course."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Phase 2: Build Real Projects With an AI Pair Programmer (Weeks 5–10)"}]},{"type":"paragraph","content":[{"type":"text","text":"Tutorials teach syntax. Projects teach engineering. Start building embarrassingly small things and grow:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"5"},{"type":"text","text":" — Project: Command-line to-do app; What it teaches: Functions, file I/O, program structure"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"6–7"},{"type":"text","text":" — Project: Personal website with HTML/CSS/JS; What it teaches: How the web works, debugging in the browser"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"8–10"},{"type":"text","text":" — Project: Full mini-app (e.g. expense tracker with a database); What it teaches: APIs, databases, putting it all together"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"For each project, make AI do the scaffolding while you do the thinking. A strong workflow:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Describe the design first."},{"type":"text","text":" \"I want a to-do CLI app with add, list, and delete commands, storing data in a JSON file. Suggest a file structure and explain your choices.\""}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Generate one piece at a time."},{"type":"text","text":" Never ask for the whole app at once — you won''t understand it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Break it on purpose."},{"type":"text","text":" Change things, run it, read the errors. Ask AI to explain "},{"type":"text","marks":[{"type":"italic"}],"text":"why"},{"type":"text","text":" the error happened, not just to fix it."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Example — after AI generates your first function, interrogate it:"}]},{"type":"codeBlock","attrs":{"language":null},"content":[{"type":"text","text":"def add_task(tasks, title):\n    tasks.append({\"title\": title, \"done\": False})\n    return tasks\n"}]},{"type":"codeBlock","attrs":{"language":null},"content":[{"type":"text","text":"Explain this function line by line. What is `append` doing? What would\nhappen if `tasks` were a dictionary instead of a list? How would you\nwrite a test for this function?\n"}]},{"type":"paragraph","content":[{"type":"text","text":"Congratulations — you just studied data structures, defensive thinking, and testing from six lines of code. "},{"type":"text","marks":[{"type":"italic"}],"text":"That"},{"type":"text","text":" is leverage."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Phase 3: Learn to Think Like an Engineer (Weeks 11–16+)"}]},{"type":"paragraph","content":[{"type":"text","text":"This is what separates kickass engineers from people who can prompt. Drill these deliberately:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Decomposition."},{"type":"text","text":" Given any feature (\"user login\"), practice breaking it into small steps before touching AI or code. AI executes plans; engineers make them."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Reading code."},{"type":"text","text":" Ask AI to walk you through a small open-source file line by line. Reading is 80% of professional engineering."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Testing."},{"type":"text","text":" A "},{"type":"text","marks":[{"type":"italic"}],"text":"test"},{"type":"text","text":" is code that automatically checks your code works. Ask AI: \"Write tests for this function and explain what each test proves.\" Then make a habit of it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Debugging systematically."},{"type":"text","text":" When something breaks: reproduce it, form a hypothesis, test the hypothesis. Ask AI to "},{"type":"text","marks":[{"type":"italic"}],"text":"guide"},{"type":"text","text":" your debugging with questions instead of handing you the fix."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"System design basics."},{"type":"text","text":" How does a request travel from browser to server to database and back? Draw it, then have AI critique your diagram."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"A milestone to aim for: build one project "},{"type":"text","marks":[{"type":"bold"}],"text":"without AI writing any logic"},{"type":"text","text":" — use it only for explanations and reviews. If you can do that, you own the fundamentals."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Pitfalls That Kill AI-Accelerated Careers"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Blind copy-paste."},{"type":"text","text":" If you can''t explain it, don''t ship it. Interviewers and production incidents will find out."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Tutorial hell 2.0."},{"type":"text","text":" Generating ten AI apps teaches less than deeply understanding one. Depth beats volume."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Leaking secrets."},{"type":"text","text":" Never paste passwords, API keys, or private company code into public AI tools. Use placeholder values instead."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Skipping computer science basics."},{"type":"text","text":" You don''t need a degree, but you do need to understand how the internet, databases, and version control work. AI can''t compensate for missing mental models forever."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"No public proof."},{"type":"text","text":" Hiring managers trust GitHub profiles and live demos, not claims. Push code early and often."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Your 90-Day Plan at a Glance"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Days 1–30"},{"type":"text","text":" — Focus: One language + Git + terminal, AI as tutor; Done looks like: You can solve beginner exercises and explain your solutions"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Days 31–60"},{"type":"text","text":" — Focus: Two small projects, AI as pair programmer; Done looks like: Two repos on GitHub with README files you wrote yourself"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Days 61–90"},{"type":"text","text":" — Focus: One bigger project + testing + reading others'' code; Done looks like: A deployed app, tests in the repo, and one open-source contribution or detailed code review"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Takeaways and Next Steps"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"AI compresses the time from zero to building, but "},{"type":"text","marks":[{"type":"bold"}],"text":"understanding is still the job"},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use AI in three roles: "},{"type":"text","marks":[{"type":"bold"}],"text":"tutor"},{"type":"text","text":" (explain), "},{"type":"text","marks":[{"type":"bold"}],"text":"pair programmer"},{"type":"text","text":" (draft), "},{"type":"text","marks":[{"type":"bold"}],"text":"reviewer"},{"type":"text","text":" (critique)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Build in public from day one — your GitHub is your résumé."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Depth beats breadth: one language, a few projects, deeply understood."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Next steps for this week:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Install Python or Node.js, create a GitHub account, and learn basic terminal commands."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Complete five AI-tutored exercises using the prompt pattern from Phase 1."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Start your to-do CLI project and push it to GitHub — messy is fine."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The engineers who thrive in the AI era won''t be the ones who type the fastest or memorize the most syntax. They''ll be the ones who think clearly, verify rigorously, and learn relentlessly — with AI multiplying every hour they put in. Start today, and let it multiply yours."}]}]}'::jsonb,
  'From Zero to Kickass Software Engineer: Using AI as Your Unfair Advantage',
  'No coding background? Learn how to use AI as tutor, pair programmer, and reviewer to become a job-ready software engineer.',
  (SELECT id FROM users WHERE email = 'gerald@geraldvillorente.com'),
  NULL
)
ON CONFLICT (slug) DO UPDATE SET
  title = EXCLUDED.title,
  excerpt = EXCLUDED.excerpt,
  content = EXCLUDED.content,
  meta_title = EXCLUDED.meta_title,
  meta_description = EXCLUDED.meta_description,
  author_id = COALESCE(EXCLUDED.author_id, posts.author_id),
  updated_at = NOW();

DELETE FROM post_categories WHERE post_id = (SELECT id FROM posts WHERE slug = 'from-zero-to-kickass-engineer-with-ai');
INSERT INTO categories (name, slug) VALUES ('Career', 'career')
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name;
INSERT INTO post_categories (post_id, category_id)
SELECT p.id, c.id FROM posts p, categories c
WHERE p.slug = 'from-zero-to-kickass-engineer-with-ai' AND c.slug = 'career'
ON CONFLICT DO NOTHING;

DELETE FROM post_tags WHERE post_id = (SELECT id FROM posts WHERE slug = 'from-zero-to-kickass-engineer-with-ai');
INSERT INTO tags (name, slug) VALUES
  ('career-change', 'career-change'),
  ('ai-assisted-coding', 'ai-assisted-coding'),
  ('software-engineering', 'software-engineering'),
  ('beginners', 'beginners'),
  ('learning-to-code', 'learning-to-code')
ON CONFLICT (slug) DO NOTHING;
INSERT INTO post_tags (post_id, tag_id)
SELECT p.id, t.id FROM posts p, tags t
WHERE p.slug = 'from-zero-to-kickass-engineer-with-ai' AND t.slug IN ('career-change', 'ai-assisted-coding', 'software-engineering', 'beginners', 'learning-to-code')
ON CONFLICT DO NOTHING;

COMMIT;
